#include <DHT.h>

// =====================================================
// ANALOG SENSORS
// =====================================================

#define LDR_PIN   A0
#define TEMP_PIN  A1
#define AIR_PIN   A2
#define DHT_PIN   A3

#define DHTTYPE DHT11

DHT dht(DHT_PIN, DHTTYPE);


// =====================================================
// HC-SR04 - ZONE 1
// =====================================================

#define TRIG1 2
#define ECHO1 4

// =====================================================
// HC-SR04 - ZONE 2
// =====================================================

#define TRIG2 7
#define ECHO2 8

// =====================================================
// HC-SR04 - ZONE 3
// =====================================================

#define TRIG3 12
#define ECHO3 13


// =====================================================
// LED OUTPUTS - ALL PWM
// =====================================================

// Zone 1
#define WHITE1 3
#define YELLOW1 5

// Zone 2
#define WHITE2 6
#define YELLOW2 9

// Zone 3
#define WHITE3 10
#define YELLOW3 11


// =====================================================
// SETTINGS
// =====================================================

#define OBJECT_DISTANCE 30


// =====================================================
// READ HC-SR04
// =====================================================

float readDistance(int trigPin, int echoPin)
{
  digitalWrite(trigPin, LOW);
    delayMicroseconds(3);

      digitalWrite(trigPin, HIGH);
        delayMicroseconds(10);

          digitalWrite(trigPin, LOW);

            long duration = pulseIn(echoPin, HIGH, 30000);

              if (duration == 0)
                {
                    return 999.0;
                      }

                        float distance = duration * 0.0343 / 2.0;

                          return distance;
                          }


                          // =====================================================
                          // SETUP
                          // =====================================================

                          void setup()
                          {
                            Serial.begin(9600);

                              dht.begin();

                                // HC-SR04
                                  pinMode(TRIG1, OUTPUT);
                                    pinMode(ECHO1, INPUT);

                                      pinMode(TRIG2, OUTPUT);
                                        pinMode(ECHO2, INPUT);

                                          pinMode(TRIG3, OUTPUT);
                                            pinMode(ECHO3, INPUT);

                                              // LED outputs
                                                pinMode(WHITE1, OUTPUT);
                                                  pinMode(YELLOW1, OUTPUT);

                                                    pinMode(WHITE2, OUTPUT);
                                                      pinMode(YELLOW2, OUTPUT);

                                                        pinMode(WHITE3, OUTPUT);
                                                          pinMode(YELLOW3, OUTPUT);

                                                            // Start with all LEDs OFF
                                                              analogWrite(WHITE1, 0);
                                                                analogWrite(YELLOW1, 0);

                                                                  analogWrite(WHITE2, 0);
                                                                    analogWrite(YELLOW2, 0);

                                                                      analogWrite(WHITE3, 0);
                                                                        analogWrite(YELLOW3, 0);

                                                                          delay(1000);
                                                                          }


                                                                          // =====================================================
                                                                          // MAIN LOOP
                                                                          // =====================================================

                                                                          void loop()
                                                                          {
                                                                            // ===================================================
                                                                              // 1. LDR
                                                                                // ===================================================

                                                                                  int lightValue = analogRead(LDR_PIN);

                                                                                    // More light = lower lamp brightness
                                                                                      // Less light = higher lamp brightness

                                                                                        int brightness = map(
                                                                                            lightValue,
                                                                                                0,
                                                                                                    1023,
                                                                                                        255,
                                                                                                            0
                                                                                                              );

                                                                                                                brightness = constrain(brightness, 0, 255);


                                                                                                                  // ===================================================
                                                                                                                    // 2. LM35 TEMPERATURE
                                                                                                                      // ===================================================

                                                                                                                        int tempRaw = analogRead(TEMP_PIN);

                                                                                                                          float voltage = tempRaw * (5.0 / 1023.0);

                                                                                                                            float temperature = voltage * 100.0;


                                                                                                                              // ===================================================
                                                                                                                                // 3. AIR QUALITY SIMULATOR
                                                                                                                                  // ===================================================

                                                                                                                                    int airValue = analogRead(AIR_PIN);


                                                                                                                                      // ===================================================
                                                                                                                                        // 4. HUMIDITY
                                                                                                                                          // ===================================================

                                                                                                                                            float humidity = dht.readHumidity();

                                                                                                                                              if (isnan(humidity))
                                                                                                                                                {
                                                                                                                                                    humidity = 50.0;
                                                                                                                                                      }


                                                                                                                                                        // ===================================================
                                                                                                                                                          // 5. BASE COLOR
                                                                                                                                                            // ===================================================

                                                                                                                                                              float whiteRatio = 0.50;
                                                                                                                                                                float yellowRatio = 0.50;


                                                                                                                                                                  // ===================================================
                                                                                                                                                                    // TEMPERATURE EFFECT
                                                                                                                                                                      // ===================================================

                                                                                                                                                                        if (temperature > 15.0)
                                                                                                                                                                          {
                                                                                                                                                                              float effect = constrain(
                                                                                                                                                                                    temperature,
                                                                                                                                                                                          15.0,
                                                                                                                                                                                                40.0
                                                                                                                                                                                                    );

                                                                                                                                                                                                        effect = (effect - 15.0) / 25.0;

                                                                                                                                                                                                            effect *= 0.30;

                                                                                                                                                                                                                whiteRatio += effect;
                                                                                                                                                                                                                    yellowRatio -= effect;
                                                                                                                                                                                                                      }
                                                                                                                                                                                                                        else
                                                                                                                                                                                                                          {
                                                                                                                                                                                                                              float effect = constrain(
                                                                                                                                                                                                                                    temperature,
                                                                                                                                                                                                                                          0.0,
                                                                                                                                                                                                                                                15.0
                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                        effect = (15.0 - effect) / 15.0;

                                                                                                                                                                                                                                                            effect *= 0.30;

                                                                                                                                                                                                                                                                yellowRatio += effect;
                                                                                                                                                                                                                                                                    whiteRatio -= effect;
                                                                                                                                                                                                                                                                      }


                                                                                                                                                                                                                                                                        // ===================================================
                                                                                                                                                                                                                                                                          // AIR QUALITY EFFECT
                                                                                                                                                                                                                                                                            // ===================================================

                                                                                                                                                                                                                                                                              if (airValue > 300)
                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                    float airEffect = constrain(
                                                                                                                                                                                                                                                                                          airValue,
                                                                                                                                                                                                                                                                                                300,
                                                                                                                                                                                                                                                                                                      900
                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                              airEffect =
                                                                                                                                                                                                                                                                                                                    (airEffect - 300.0) / 600.0;

                                                                                                                                                                                                                                                                                                                        airEffect *= 0.25;

                                                                                                                                                                                                                                                                                                                            whiteRatio += airEffect;
                                                                                                                                                                                                                                                                                                                                yellowRatio -= airEffect;
                                                                                                                                                                                                                                                                                                                                  }


                                                                                                                                                                                                                                                                                                                                    // ===================================================
                                                                                                                                                                                                                                                                                                                                      // HUMIDITY EFFECT
                                                                                                                                                                                                                                                                                                                                        // ===================================================

                                                                                                                                                                                                                                                                                                                                          if (humidity > 70.0)
                                                                                                                                                                                                                                                                                                                                            {
                                                                                                                                                                                                                                                                                                                                                float humidityEffect = constrain(
                                                                                                                                                                                                                                                                                                                                                      humidity,
                                                                                                                                                                                                                                                                                                                                                            70.0,
                                                                                                                                                                                                                                                                                                                                                                  100.0
                                                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                                                          humidityEffect =
                                                                                                                                                                                                                                                                                                                                                                                (humidityEffect - 70.0) / 30.0;

                                                                                                                                                                                                                                                                                                                                                                                    humidityEffect *= 0.35;

                                                                                                                                                                                                                                                                                                                                                                                        yellowRatio += humidityEffect;
                                                                                                                                                                                                                                                                                                                                                                                            whiteRatio -= humidityEffect;
                                                                                                                                                                                                                                                                                                                                                                                              }


                                                                                                                                                                                                                                                                                                                                                                                                // ===================================================
                                                                                                                                                                                                                                                                                                                                                                                                  // LIMIT RATIOS
                                                                                                                                                                                                                                                                                                                                                                                                    // ===================================================

                                                                                                                                                                                                                                                                                                                                                                                                      whiteRatio =
                                                                                                                                                                                                                                                                                                                                                                                                          constrain(whiteRatio, 0.0, 1.0);

                                                                                                                                                                                                                                                                                                                                                                                                            yellowRatio =
                                                                                                                                                                                                                                                                                                                                                                                                                constrain(yellowRatio, 0.0, 1.0);


                                                                                                                                                                                                                                                                                                                                                                                                                  // ===================================================
                                                                                                                                                                                                                                                                                                                                                                                                                    // FINAL LED BRIGHTNESS
                                                                                                                                                                                                                                                                                                                                                                                                                      // =====================================================

                                                                                                                                                                                                                                                                                                                                                                                                                        int whiteBrightness =
                                                                                                                                                                                                                                                                                                                                                                                                                            brightness * whiteRatio;

                                                                                                                                                                                                                                                                                                                                                                                                                              int yellowBrightness =
                                                                                                                                                                                                                                                                                                                                                                                                                                  brightness * yellowRatio;


                                                                                                                                                                                                                                                                                                                                                                                                                                    // ===================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                      // 6. READ DISTANCES
                                                                                                                                                                                                                                                                                                                                                                                                                                        // ===================================================

                                                                                                                                                                                                                                                                                                                                                                                                                                          float distance1 =
                                                                                                                                                                                                                                                                                                                                                                                                                                              readDistance(TRIG1, ECHO1);

                                                                                                                                                                                                                                                                                                                                                                                                                                                delay(30);

                                                                                                                                                                                                                                                                                                                                                                                                                                                  float distance2 =
                                                                                                                                                                                                                                                                                                                                                                                                                                                      readDistance(TRIG2, ECHO2);

                                                                                                                                                                                                                                                                                                                                                                                                                                                        delay(30);

                                                                                                                                                                                                                                                                                                                                                                                                                                                          float distance3 =
                                                                                                                                                                                                                                                                                                                                                                                                                                                              readDistance(TRIG3, ECHO3);


                                                                                                                                                                                                                                                                                                                                                                                                                                                                // ===================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // 7. ZONE 1
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ===================================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (distance1 <= OBJECT_DISTANCE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            analogWrite(WHITE1, 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                analogWrite(YELLOW1, 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          analogWrite(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                WHITE1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      whiteBrightness
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              analogWrite(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    YELLOW1,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          yellowBrightness
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // ===================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // 8. ZONE 2
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // ===================================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (distance2 <= OBJECT_DISTANCE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              analogWrite(WHITE2, 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  analogWrite(YELLOW2, 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            analogWrite(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  WHITE2,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        whiteBrightness
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                analogWrite(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      YELLOW2,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            yellowBrightness
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ===================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // 9. ZONE 3
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ===================================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (distance3 <= OBJECT_DISTANCE)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                analogWrite(WHITE3, 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    analogWrite(YELLOW3, 0);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        else
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              analogWrite(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    WHITE3,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          whiteBrightness
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  analogWrite(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        YELLOW3,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              yellowBrightness
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }


                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // ===================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // SERIAL MONITOR
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // =====================================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Serial.println("-----------------------------");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Serial.print("LDR: ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Serial.println(lightValue);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Serial.print("Brightness: ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Serial.println(brightness);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Serial.print("Temperature: ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Serial.print(temperature);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Serial.println(" C");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Serial.print("Air: ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Serial.println(airValue);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Serial.print("Humidity: ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Serial.print(humidity);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Serial.println(" %");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Serial.print("Zone 1: ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Serial.print(distance1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          Serial.println(" cm");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            Serial.print("Zone 2: ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              Serial.print(distance2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                Serial.println(" cm");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  Serial.print("Zone 3: ");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Serial.print(distance3);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      Serial.println(" cm");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        delay(200);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
